// Same-origin API bridge. Static Sites preview remains available when no API is present.
window.BlueMintBackend={enabled:false,session:null,config:null};
const apiState=window.BlueMintBackend;
async function api(path,options={}){const response=await fetch('/api'+path,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...(apiState.session?.csrf?{'X-CSRF-Token':apiState.session.csrf}:{}),...options.headers}});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data}
const normalizeLaunch=t=>({...t,id:Number(t.id),seed:Number(BigInt(t.seedUnits||'0'))/1e6});
apiState.saveLaunch=async values=>{if(!apiState.session?.wallet)throw new Error('Connect and sign in with your wallet before saving a launch.');return normalizeLaunch(await api('/launches',{method:'POST',headers:{'Idempotency-Key':values.requestKey},body:JSON.stringify({...values,seed:String(values.seed)})}))};
async function walletLogin(){const provider=window.phantom?.solana||window.solana||window.solflare;if(!provider?.connect||!provider?.signMessage){open('<h2>Open your Solana wallet.</h2><p class="modal-sub">Use a browser with Phantom or Solflare installed. BlueMint verifies a signed message; it never requests your private key.</p>');return}try{const connected=await provider.connect(),wallet=(connected.publicKey||provider.publicKey).toString();const challenge=await api('/auth/challenge',{method:'POST',body:JSON.stringify({wallet})});const signed=await provider.signMessage(new TextEncoder().encode(challenge.message),'utf8'),bytes=signed.signature||signed;const signature=btoa(String.fromCharCode(...new Uint8Array(bytes)));apiState.session=await api('/auth/verify',{method:'POST',body:JSON.stringify({id:challenge.id,signature})});walletLabel();await loadWatchlist();toast('Wallet verified. No transaction authorized.')}catch(error){toast(error.message)}}
function walletLabel(){document.querySelectorAll('[data-wallet-connect]').forEach(b=>{b.textContent=apiState.session?.wallet?apiState.session.wallet.slice(0,4)+'…'+apiState.session.wallet.slice(-4)+' · Sign out':'Connect wallet';b.onclick=walletAction});document.querySelectorAll('[data-platform-setup]').forEach(a=>a.hidden=apiState.session?.wallet!==apiState.config?.platformOwner)}
function walletAction(){if(!apiState.session?.wallet)return walletLogin();open(`<h2>Wallet connected</h2><p class="modal-sub">${esc(apiState.session.wallet)}</p><button class="primary full" id="disconnectWallet">Sign out</button>`);$('#disconnectWallet').onclick=async()=>{try{await api('/auth/logout',{method:'POST',body:'{}'});apiState.session=null;walletLabel();modal.close();toast('Signed out')}catch(e){toast(e.message)}}}

async function loadWatchlist(){if(!apiState.session?.wallet)return;const data=await api('/watchlist');saved=data.ids.map(Number);render()}
async function loadLaunches(){const data=await api('/launches?limit=100');tokens=data.items.map(normalizeLaunch);drafts=[];render();const newCount=$('[data-filter="new"] span');if(newCount)newCount.textContent=String(tokens.filter(t=>t.status==='new').length);const metrics=$$('.metrics>div');if(metrics[0])metrics[0].innerHTML='<span>Verified 24h volume</span><strong>— <small>USDC</small></strong><label>Market indexer not connected</label>';if(metrics[1])metrics[1].innerHTML='<span>Verified liquidity added</span><strong>— <small>USDC</small></strong><label>On-chain executor not deployed</label>';if(metrics[2])metrics[2].innerHTML=`<span>Saved launches</span><strong>${tokens.length} <small>DRAFTS</small></strong><label>Wallet-authenticated profiles</label>`;$('.featured-section').hidden=true;$('.market-strip').hidden=true;const title=$('.market-foot');if(title)title.innerHTML='<span>Persistent launch registry · live trading not configured</span>';}
const originalMintPage=showMint;showMint=function(){if(!apiState.enabled)return originalMintPage();showServerMint()};
async function showServerMint(){homeMain.hidden=true;detailMain.hidden=false;if(chartObserver){chartObserver.disconnect();chartObserver=null}document.title='The Mint — BlueMint';detailMain.innerHTML='<div class="empty">Loading The Mint ledger…</div>';try{const data=await api('/mint');if(location.hash!=='#mint')return;const fmtU=v=>money(Number(BigInt(v))/1e6);detailMain.innerHTML=`<div class="token-breadcrumb"><a href="#">← Discovery</a><span>/ The Mint</span></div><div class="mint-section-heading"><div><span class="eyebrow blue">PERSISTENT ACCOUNTING</span><h1>The Mint.</h1><p class="modal-sub">Operator-reported entries. Not independently verified on-chain.</p></div></div><div class="mint-stats"><div><span>Reported fees collected</span><strong>${fmtU(data.totals.collectedUnits)} <small>USDC</small></strong></div><div><span>Reported liquidity allocation</span><strong>${fmtU(data.totals.liquidityAllocatedUnits)} <small>USDC</small></strong></div><div><span>Reported deployed capital</span><strong>${fmtU(data.totals.liquidityDeployedUnits)} <small>USDC</small></strong></div><div><span>Reported pending allocation</span><strong>${fmtU(data.totals.liquidityPendingUnits)} <small>USDC</small></strong></div></div><section class="mint-report-grid"><div class="mint-growth"><div class="mint-panel-heading"><h3>Built coin by coin.</h3><span>CONCEPT ANIMATION</span></div><div class="mint-growing-art"><picture><source media="(prefers-reduced-motion: reduce)" srcset="assets/how-growing.png"><img src="assets/how-growing.gif" alt="Illustrative USDC chip stack animation"></picture></div></div><div class="mint-split-panel"><h3>One fee. Two destinations.</h3><div class="split"><span>Launchpad treasury</span><b>0.50%</b></div><div class="split"><span>Token liquidity</span><b>0.75%</b></div><p>1.25% launchpad fee plus Raydium fees. Allocation splits recorded collected fees 40% / 60%. This server does not collect fees or execute buybacks.</p></div></section><section class="mint-ledger"><div class="mint-panel-heading"><h3>Append-only operator ledger</h3></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Launch</th><th>Event</th><th>USDC</th><th>Source</th></tr></thead><tbody>${data.events.length?data.events.map(e=>`<tr><td>${esc(e.created_at)}</td><td><a href="#token/${e.launch_id}">${esc(e.launch_id)}</a></td><td>${esc(e.kind)}</td><td>${fmtU(e.units)}</td><td>OPERATOR REPORT</td></tr>`).join(''):'<tr><td colspan="5">No ledger entries. No fees or liquidity executions have been recorded.</td></tr>'}</tbody></table></div></section><div class="mint-disclosure"><p>Financial amounts are accounting records, not balances guaranteed by a smart contract. Mainnet launches, live charts and liquidity execution are unavailable until the chain integrations are complete.</p></div>`}catch(e){detailMain.innerHTML=`<div class="empty">Unable to load ledger: ${esc(e.message)}</div>`}}
const originalCreatePage=showCreate;showCreate=function(){originalCreatePage();const walletPanel=document.createElement('section');walletPanel.className='launch-wallet-panel';walletPanel.innerHTML='<div><span class="eyebrow blue">YOUR LAUNCH WALLET</span><h3>Connect to save your launch.</h3><p>Sign-in proves ownership. Transactions require a separate wallet approval.</p></div><button type="button" class="pixel-mint-button" data-wallet-connect>Connect wallet</button><a href="#setup" class="text-btn" data-platform-setup hidden>Platform setup</a>';$('#createForm').prepend(walletPanel);walletLabel();if(!apiState.enabled)return;$('.mint-demo-pill').textContent='PERSISTENT DRAFT MODE';$('.create-consent span').textContent='I understand this saves a public launch draft linked to my wallet. It does not mint a token or move funds.';$('.identity-lock span').textContent='Profile is immutable in this registry; on-chain metadata lock is not deployed.';const box=document.createElement('div');box.className='info-box';box.textContent='Connected backend: sign in with your Solana wallet to save. Launch identity, PFP and social links become publicly available in this registry.';$('#createForm').prepend(box)};
(async()=>{try{const response=await fetch('/api/config');if(!response.ok)return;const config=await response.json();if(config.apiVersion!==1)return;apiState.enabled=true;apiState.config=config;apiState.session=await api('/auth/me');walletLabel();$('.notice').innerHTML='<span>BACKEND PREVIEW</span> Persistent profiles · Wallet sign-in · On-chain trading not deployed';await loadLaunches();await loadWatchlist();route();const stream=new EventSource('/api/events');stream.addEventListener('refresh',async()=>{try{await loadLaunches();if(location.hash==='#mint')showServerMint()}catch{}});document.addEventListener('click',e=>{const star=e.target.closest('[data-save]');if(star&&apiState.session?.wallet){const id=Number(star.dataset.save);setTimeout(()=>api('/watchlist',{method:'POST',body:JSON.stringify({launchId:String(id),saved:saved.includes(id)})}).catch(err=>toast(err.message)),0)}})}catch(e){if(apiState.enabled){$('.notice').textContent='Backend unavailable: '+e.message;tokens=[];render()}else console.info('Static preview mode')}})();

async function showChainStatus(){const box=$('#chainStatus');if(!box)return;try{const s=await api('/chain/status');if(!box.isConnected)return;box.innerHTML=`<b>LaunchLab connection</b><div>Network: ${esc(s.network)} · Platform fee: ${s.platformFeeConnected?'verified at 1.25%':'not connected'}</div><div>Automated 40/60 split: not deployed · Post-graduation fee: not connected</div><p>${esc(s.issue?'Minting is unavailable while the platform configuration is being verified.':'Platform verified. Devnet wallet-signed preparation is '+(s.mintPreparationReady?'enabled.':'disabled.'))}</p>`}catch{box.textContent='Unable to verify LaunchLab connection.'}}
const createWithWallet=showCreate;showCreate=function(){createWithWallet();const status=document.createElement('div');status.id='chainStatus';status.className='integration-status';status.textContent='Checking LaunchLab configuration…';$('#createForm').append(status);if(apiState.enabled)showChainStatus();else status.textContent='Static preview · LaunchLab not connected.'};
const renderWithProfile=renderPage;renderPage=function(t){renderWithProfile(t);if(!apiState.enabled)return;const panel=document.createElement('section');panel.className='chain-actions';panel.innerHTML='<span class="eyebrow blue">DEVNET LAUNCH</span><h3>Prepare your token mint.</h3><p>Test-network minting only. This creates the launch curve without an initial buy. Your draft seed commitment is not deposited. Mainnet trading and automated liquidity remain unavailable.</p><button class="pixel-mint-button" id="prepareChain">Check & prepare mint</button><button class="text-btn" id="confirmChain">Check confirmation</button><p id="chainResult" role="status"></p>';detailMain.append(panel);const output=panel.querySelector('#chainResult');panel.querySelector('#prepareChain').onclick=async()=>{try{if(!apiState.session?.wallet){location.hash='create';toast('Connect your wallet on the launch page first.');return}output.textContent='Verifying devnet configuration and simulating…';const prepared=await api(`/launches/${t.id}/prepare`,{method:'POST',body:'{}'});open(`<div class="eyebrow blue">DEVNET TRANSACTION REVIEW</div><h2>Create ${esc(t.ticker)} on devnet</h2><p class="modal-sub">Mint: ${esc(prepared.mint)}<br>Network: Solana devnet<br>Initial buy: 0 USDC<br>Devnet SOL rent and network fees apply. The wallet shows transaction details before you sign.</p><button class="pixel-mint-button" id="signMint">Review in wallet</button>`);$('#signMint').onclick=async()=>{try{$('#signMint').disabled=true;const signed=await BlueMintWallet.signPrepared(prepared.transaction,apiState.session.wallet);const result=await api(`/launches/${t.id}/submit`,{method:'POST',body:JSON.stringify({transaction:signed})});modal.close();output.textContent='Submitted on devnet: '+result.signature+'. Use Check confirmation after finalization.'}catch(e){$('#signMint').disabled=false;toast(e.message)}}}catch(e){output.textContent=e.message}};panel.querySelector('#confirmChain').onclick=async()=>{try{const result=await api(`/launches/${t.id}/confirm`,{method:'POST',body:'{}'});output.textContent='Finalized devnet mint: '+result.mint+'. Live trading is not enabled.'}catch(e){output.textContent=e.message}};api(`/launches/${t.id}/chain`).then(r=>{if(output.isConnected&&r.launch)output.textContent=r.launch.status+' · devnet mint '+r.launch.mint}).catch(()=>{})};
